function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // trust vs mistrust stage
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/8, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '14px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('0-1', W/8, H/2);

  // autonomy vs shame stage
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fillText('1-3', W/4, H/2);

  // initiative vs guilt stage
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fillText('3-6', W/2, H/2);

  // industry vs inferiority stage
  ctx.beginPath();
  ctx.arc(W*3/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fillText('6-12', W*3/4, H/2);

  // identity vs role confusion stage
  ctx.beginPath();
  ctx.arc(W*7/8, H/2, 20 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fillText('12-18', W*7/8, H/2);

  // intimacy vs isolation stage
  ctx.beginPath();
  ctx.arc(W*7/8, H*3/4, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fillText('18-40', W*7/8, H*3/4);

  // generativity vs stagnation stage
  ctx.beginPath();
  ctx.arc(W/2, H*3/4, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fillText('40-65', W/2, H*3/4);

  // integrity vs despair stage
  ctx.beginPath();
  ctx.arc(W/8, H*3/4, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.fillText('65+', W/8, H*3/4);

  // lines connecting stages
  ctx.beginPath();
  ctx.moveTo(W/8, H/2);
  ctx.lineTo(W/4, H/2);
  ctx.lineTo(W/2, H/2);
  ctx.lineTo(W*3/4, H/2);
  ctx.lineTo(W*7/8, H/2);
  ctx.lineTo(W*7/8, H*3/4);
  ctx.lineTo(W/2, H*3/4);
  ctx.lineTo(W/8, H*3/4);
  ctx.stroke();

  ctx.restore();
}
